import React, { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import axios from 'axios'; // Axios 임포트
import './MedicineInfo.css';

function MedicineInfo() {
  const { symptomName } = useParams();
  const [medicines, setMedicines] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchMedicines = async () => {
      try {
        const response = await axios.get(`/api/medicines/symptom/${symptomName}`);
        console.log('API 호출 결과:', response.data); // 추가된 로그
        setMedicines(response.data);
      } catch (err) {
        setError('Error fetching data');
      } finally {
        setLoading(false);
      }
    };

    fetchMedicines();
  }, [symptomName]);

  if (loading) return <div>Loading...</div>;
  if (error) return <div>{error}</div>;

  return (
    <div className="medicine-info-container">
      <header className="medicine-info-header">
        <Link to="/">
          <img src="logo1.png" className="App-logo" alt="logo" />
        </Link>
      </header>
      <main className="medicine-info-main">
        <h2>Medicine Information for: {symptomName}</h2>
        {medicines.length > 0 ? (
          <ul>
            {medicines.map(medicine => (
              <li key={medicine.id}>
                <h3>{medicine.Medicine_Name}</h3>
                <p>Main Ingredients: {medicine.Main_Ingredients}</p>
                <p>Effects: {medicine.Effects}</p>
                <p>Dosage: {medicine.Dosage_by_Age}</p>
                <p>Company: {medicine.Pharmaceutical_Company}</p>
                <img src={medicine.Image_Path} alt={medicine.Medicine_Name} />
              </li>
            ))}
          </ul>
        ) : (
          <p>No medicines found for this symptom.</p>
        )}
      </main>
    </div>
  );
}

export default MedicineInfo;
